/* ===== 93_screen_fixes.css ===== */
/* ==========================================================
   93_screen_fixes.css â€” Full responsive + alignment remade
   Fixes: overflow clipping, alignment drift, text hiding,
   inversion readability, missing vars, breakpoint gaps.
   ========================================================== */

/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 1. GLOBAL BOX-MODEL SAFETY
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Prevent horizontal scroll bleed at root */
body.chkAppRoot,
body.chkAppRoot .chkApp {
  overflow-x: clip;
}

/* All flex children inside chkApp should not shrink past content */
.chkApp * {
  min-width: 0;
  box-sizing: border-box;
}

/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 2. ALIGNMENT â€” SHELL HEADER
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.chkApp .appShellHeader {
  display: flex;
  align-items: center;
  gap: 0;
  /* Prevent items from overflowing shell at narrow widths */
  overflow: visible;
  flex-wrap: nowrap;
}

/* Context actions cluster â€” keep items aligned + spaced */
.chkApp .shellContextActions {
  display: flex;
  align-items: center;
  gap: var(--theme-shell-context-gap, 0.48rem);
  flex-shrink: 0;
  overflow: visible;
  flex-wrap: nowrap;
  max-width: 100%;
}

/* Shell title â€” flexible, no unwanted clipping */
.chkApp .shellTitle {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--theme-shell-title-size);
  font-weight: var(--theme-shell-title-weight);
  color: var(--text-main);
  letter-spacing: -0.012em;
}

/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 3. ALIGNMENT â€” SEARCH PAGE FILTERS + TOOLBAR
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Filter bar â€” always flex-wrap so items never disappear */
.chkApp .searchFilterCardDense .sapUiCompFilterBarToolbar,
.chkApp .searchFilterCardDense .sapUiCompSmartFilterBar .sapMTB,
.chkApp .searchFilterCardDense .sapUiCompFilterBarToolbar.sapMTBNewFlex,
.chkApp .searchFilterCardDense .sapUiCompSmartFilterBar .sapMTB.sapMTBNewFlex {
  flex-wrap: wrap;
  align-items: center;
  row-gap: 0.34rem;
  column-gap: 0.28rem;
  min-height: 0;
  height: auto;
  /* Remove any overflow:hidden that can clip popups */
  overflow: visible;
}

/* Action toolbar â€” keep overflow visible so dropdowns show */
.chkApp .searchResultsActionRail.sapMTBNewFlex,
.chkApp .searchSmartToolbarRail.sapMTBNewFlex {
  overflow: visible;
}

/* Prevent toolbar items shrinking to 0 */
.chkApp .searchResultsActionRail .sapMBtn,
.chkApp .searchSmartToolbarRail .sapMBtn,
.chkApp .searchSmartToolbarRail .sapMMenuBtn {
  flex: 0 0 auto;
  min-width: 0;
  max-width: 100%;
}

/* Filter items â€” responsive clamp so they never overflow/hide */
.chkApp .searchFilterExperienceShell .sapUiCompFilterBarItem,
.chkApp .searchFilterExperienceShell .sapUiCompSmartFilterBar .sapUiCompFilterBarItem {
  min-width: clamp(6.8rem, 11vw, 8.6rem);
  flex: 1 1 clamp(6.8rem, 11vw, 8.6rem);
  overflow: visible;
}

/* Toolbar spacer â€” never force overflow */
.chkApp .searchResultsActionRail .sapMTBSpacer,
.chkApp .searchSmartToolbarRail .sapMTBSpacer {
  flex: 1 1 0;
  min-width: 0;
}

/* Search KPI rail â€” align center, allow natural wrap */
.chkApp .searchHeaderKpiRail {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 0.6rem;
  width: 100%;
  min-width: 0;
}

.chkApp .kpiCard {
  min-width: 0;
  flex: 1 1 8rem;
}

/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 4. ALIGNMENT â€” SEARCH RESULTS TABLE
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Table container â€” allow horizontal scroll when needed */
.chkApp .searchResultsTable {
  overflow-x: auto;
  overflow-y: visible;
}

/* Table row cells â€” prevent text from being invisible-clipped */
.chkApp .searchResultsTable .sapMListTblHeaderCell,
.chkApp .searchResultsTable .sapMListTblCell {
  vertical-align: middle;
  overflow: visible;
  /* Clamp padding so cells look right on all screens */
  padding-block: var(--theme-table-cell-padding-block);
  padding-inline: var(--theme-table-cell-padding-inline);
}

/* Table cell text â€” graceful truncation, not invisible text */
.chkApp .searchResultsTable .sapMListTblCell .sapMText,
.chkApp .searchResultsTable .sapMListTblCell .sapMObjectIdentifierText {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  display: block;
}

/* Restore wrapping on very narrow screens */
@media (max-width: 45rem) {
  .chkApp .searchResultsTable .sapMListTblCell .sapMText,
  .chkApp .searchResultsTable .sapMListTblCell .sapMObjectIdentifierText,
  .chkApp .searchResultsTable .sapMColumnHeader {
    overflow-wrap: anywhere;
    word-break: break-word;
    white-space: normal;
    text-overflow: unset;
  }
}

/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 5. ALIGNMENT â€” DETAIL PANE
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Info cards grid â€” always fill available width */
.chkApp .detailContent .infoCardGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 11rem), 1fr));
  gap: 0.56rem;
  width: 100%;
  min-width: 0;
}

/* Info card tile â€” prevent overflow */
.chkApp .infoCardTile {
  overflow: visible;
  min-width: 0;
}

.chkApp .infoCardValue {
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* Detail stat area â€” consistent spacing all themes */
.chkApp .detailInfoCard,
.chkApp .detailSectionCard {
  min-width: 0;
  overflow: visible;
}

/* Detail toolbar â€” force visible overflow so dropdowns work */
.chkApp .detailSectionToolbar,
.chkApp .detailControlRow,
.chkApp .detailControlRowTop,
.chkApp .detailControlRowActions,
.chkApp .detailAttachmentToolbar {
  overflow: visible;
}

/* Attachment tables â€” horizontal scroll instead of clipping */
.chkApp .detailSectionBody,
.chkApp .detailAttachmentsBody {
  overflow-x: auto;
  overflow-y: visible;
}

/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 6. ALIGNMENT â€” DIALOGS
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Dialog content â€” prevent runaway width */
.chkApp .sapMDialog,
