  /* Transition presets */
  --t-fast:   120ms ease;
  --t-normal: 200ms ease;
  --t-slow:   320ms cubic-bezier(0.22, 0.61, 0.36, 1);
  --t-spring: 380ms cubic-bezier(0.175, 0.885, 0.32, 1.275);

  /* Surface elevation (light) */
  --elev-0: none;
  --elev-1: 0 1px 3px rgba(15, 32, 58, 0.06), 0 4px 12px rgba(15, 32, 58, 0.04);
  --elev-2: 0 4px 16px rgba(15, 32, 58, 0.08), 0 2px 6px rgba(15, 32, 58, 0.05);
  --elev-3: 0 8px 28px rgba(15, 32, 58, 0.1),  0 3px 10px rgba(15, 32, 58, 0.06);
  --elev-4: 0 16px 48px rgba(15, 32, 58, 0.12), 0 6px 18px rgba(15, 32, 58, 0.07);

  /* Glass quality */
  --glass-blur-sm:  10px;
  --glass-blur-md:  18px;
  --glass-blur-lg:  28px;
  --glass-sat: 140%;
}

/* Dark elevation */
body.chkAppRoot.appDark {
  --elev-1: 0 1px 3px rgba(0, 4, 14, 0.18), 0 4px 12px rgba(0, 4, 14, 0.14);
  --elev-2: 0 4px 16px rgba(0, 4, 14, 0.24), 0 2px 8px rgba(0, 4, 14, 0.16);
  --elev-3: 0 8px 28px rgba(0, 4, 14, 0.3),  0 4px 12px rgba(0, 4, 14, 0.2);
  --elev-4: 0 16px 48px rgba(0, 4, 14, 0.38), 0 8px 22px rgba(0, 4, 14, 0.26);
}

