/* Fade-in Ð¿Ñ€Ð¸ Ð¿Ð¾ÑÐ²Ð»ÐµÐ½Ð¸Ð¸ ÑÐ»ÐµÐ¼ÐµÐ½Ñ‚Ð¾Ð² */
@keyframes fadeSlideIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes modernShimmer {
  0%   { background-position: -200% center; }
  100% { background-position: 200% center; }
}

/* Skeleton shimmer (ÑÐ¾Ð²Ñ€ÐµÐ¼ÐµÐ½Ð½Ñ‹Ð¹) */
.chkApp .appSkeletonLine::after,
.chkApp .appSkeletonBlock::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    105deg,
    transparent 30%,
    rgba(255, 255, 255, 0.22) 50%,
    transparent 70%
  );
  background-size: 200% 100%;
  animation: modernShimmer 1.6s ease-in-out infinite;
}

/* Card reveal animation */
.chkApp .appSkeletonReveal {
  animation: fadeSlideIn 340ms cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

