    border-radius: var(--e-radius-card);
  }

  .chkApp .kpiCard,
  .chkApp .searchAnalyticsCard,
  .chkApp .workflowStageCard {
    padding: var(--e-sp-3);
  }

  .chkApp .searchFilterCardDense,
  .chkApp .searchResultsTable,
  .chkApp .detailSectionCard {
    padding: var(--e-sp-3);
  }
}

@media (max-width: 48rem) {
  /* Stack KPI grid */
  .chkApp .kpiGrid {
    grid-template-columns: 1fr 1fr;
  }

  /* Tighten table cells */
  .chkApp .searchResultsTable .sapMListTblRow .sapMListTblCell {
    padding-inline: var(--e-sp-3);
  }

  /* Full-width chips */
  .chkApp .uxStatChip {
    flex: 1 1 calc(50% - var(--e-sp-2));
  }
}

@media (max-width: 32rem) {
  /* Ultra-compact mode */
  .chkApp .shellContextSubtitle { display: none; }

  .chkApp .kpiGrid {
    grid-template-columns: 1fr;
  }

  .chkApp .searchResultsTable .sapMListTblRow .sapMListTblCell {
    padding-inline: var(--e-sp-2);
    padding-block:  var(--e-sp-2);
  }
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ 24. THEME TRANSITIONS â€” Smooth, not jarring
   When user switches between light/dark, everything eases.
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

html.chkAppRoot.theme-switching .chkApp *,
html.chkAppRoot.theme-switching .sapMDialog,
html.chkAppRoot.theme-switching .sapMPopover,
html.chkAppRoot.theme-switching .sapMSelectList {
  transition:
