.chkApp .kpiCard,
.chkApp .searchAnalyticsCard,
.chkApp .workflowStageCard          { contain: layout style; will-change: transform; }
.chkApp .searchResultsTable         { contain: layout; }
.chkApp .searchResultsTable .sapMListTblRow { will-change: transform; }

/* Glassmorphism layers â€” isolate to own stacking context */
.chkApp .appShellHeader,
.chkApp .searchFilterCardDense,
.chkApp .detailControlInlineCard    { isolation: isolate; }


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-2  SHELL HEADER â€” definitive command centre
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Accent gradient sweep on header top edge */
.chkApp .appShellHeader::before {
  content:        '';
  position:       absolute;
  inset-block-start: 0;
  inset-inline:   12.5% 12.5%;
  height:         1px;
  background:     linear-gradient(
    90deg,
    transparent,
    rgba(var(--accent-rgb), 0.55) 35%,
    rgba(var(--accent-rgb), 0.28) 65%,
    transparent
  );
  border-radius:  var(--e-radius-chip, 999px);
  pointer-events: none;
  z-index:        1;
}

/* Bottom fade for depth */
.chkApp .appShellHeader::after {
  content:        '';
  position:       absolute;
  inset-block-end: -1px;
  inset-inline:   0;
  height:         1px;
  background:     linear-gradient(
    90deg,
    transparent,
    rgba(var(--accent-rgb), 0.08) 50%,
    transparent
  );
  pointer-events: none;
}

/* Product title â€” enterprise wordmark weight */
.chkApp .shellProductTitle {
  font-size:         1.05rem;
  font-weight:       780;
  letter-spacing:    -0.022em;
  line-height:       1;
  font-feature-settings: "kern" 1, "ss01" 1;
  -webkit-font-smoothing: antialiased;
}

/* Context eyebrow â€” tight metadata */
.chkApp .shellContextSubtitle,
.chkApp .shellEyebrow {
  font-size:      0.68rem;
  font-weight:    600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity:        0.72;
}

/* Shell action buttons â€” pill, weighted */
.chkApp .shellActionBtn .sapMBtnInner,
.chkApp .shellUserBtn .sapMBtnInner,
.chkApp .shellThemeToggle .sapMBtnInner {
  border-radius:    999px;
  height:           var(--theme-shell-action-min-height, 2.22rem);
  min-height:       var(--theme-shell-action-min-height, 2.22rem);
  padding-inline:   var(--theme-shell-action-padding-inline, 0.74rem);
  font-size:        0.77rem;
  font-weight:      640;
  letter-spacing:   0.01em;
  gap:              var(--theme-shell-action-icon-gap, 0.42rem);
  transition:
    transform      130ms ease,
    box-shadow     200ms ease,
    border-color   180ms ease,
    background     180ms ease;
}

.chkApp .shellActionBtn:not(.sapMBtnDisabled):hover .sapMBtnInner,
.chkApp .shellUserBtn:not(.sapMBtnDisabled):hover .sapMBtnInner {
  transform:    translateY(-1px);
  box-shadow:   0 6px 18px rgba(var(--accent-rgb), 0.16),
                0 2px 6px rgba(var(--accent-rgb), 0.1);
  border-color: rgba(var(--accent-rgb), 0.36);
}

.chkApp .shellActionBtn:not(.sapMBtnDisabled):active .sapMBtnInner,
.chkApp .shellUserBtn:not(.sapMBtnDisabled):active .sapMBtnInner {
  transform:           translateY(0) scale(0.96);
  transition-duration: 55ms;
}

/* Context chip */
.chkApp .shellContextChip {
  border-radius:  999px;
  border-width:   1px;
  border-style:   solid;
  padding:        0.18rem 0.72rem;
  font-size:      0.78rem;
  font-weight:    600;
  letter-spacing: 0.005em;
  transition:     background 180ms ease, border-color 180ms ease;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-3  KPI / ANALYTICS CARDS
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* KPI value â€” optical weight, tabular, readable at speed */
.chkApp .kpiCard .sapMTitle,
.chkApp .searchAnalyticsCard .sapMTitle,
.chkApp .workflowStageCard .sapMTitle {
  font-size:             clamp(1.32rem, 2.4vw, 1.72rem);
  font-weight:           800;
  letter-spacing:        -0.03em;
  line-height:           1;
  font-variant-numeric:  tabular-nums;
  font-feature-settings: "kern" 1, "tnum" 1, "liga" 0;
}

/* Eyebrow meta label */
.chkApp .kpiLabel,
.chkApp .searchAnalyticsMeta {
  font-size:      0.68rem;
  font-weight:    700;
  letter-spacing: 0.072em;
  text-transform: uppercase;
  line-height:    1.3;
}

/* Trend indicator micro line â€” positive */
.chkApp .kpiCard.kpiTrendPositive {
  border-left: 2.5px solid rgba(var(--semantic-success-rgb), 0.7) !important;
}

/* Trend indicator micro line â€” negative */
.chkApp .kpiCard.kpiTrendNegative {
  border-left: 2.5px solid rgba(var(--semantic-danger-rgb), 0.7) !important;
}

/* Hover â€” lift with subtle accent glow */
.chkApp .kpiCard:hover,
.chkApp .searchAnalyticsCard:hover,
.chkApp .workflowStageCard:hover {
  transform:  translateY(-2px);
  box-shadow:
    0 8px 24px rgba(var(--accent-rgb), 0.09),
    0 2px 6px rgba(var(--accent-rgb), 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

body.chkAppRoot.appDark .chkApp .kpiCard:hover,
body.chkAppRoot.appDark .chkApp .searchAnalyticsCard:hover {
  box-shadow:
    0 12px 32px rgba(0, 4, 18, 0.42),
    0 4px 12px rgba(var(--accent-rgb), 0.12),
    inset 0 1px 0 rgba(210, 230, 255, 0.07);
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-4  TABLE â€” Enterprise data backbone
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Column header typography â€” authoritative */
.chkApp .searchResultsTable .sapMListTblHeaderCell .sapMText,
.chkApp .detailSectionCard .sapMListTblHeaderCell .sapMText,
.chkApp .detailAttachmentTable .sapMListTblHeaderCell .sapMText,
.chkApp .flatEditorTable .sapMListTblHeaderCell .sapMText {
  font-size:      0.67rem;
  font-weight:    800;
  letter-spacing: 0.085em;
  text-transform: uppercase;
  line-height:    1.2;
}

/* Data cell body text */
.chkApp .searchResultsTable .sapMListTblCell .sapMText,
.chkApp .searchResultsTable .sapMListTblCell .sapMObjectIdentifierText {
  font-size:   0.845rem;
  font-weight: 500;
  line-height: 1.38;
  font-feature-settings: "kern" 1;
}

/* Primary identifier column â€” heavier weight */
.chkApp .searchResultsTable .sapMListTblCell .sapMObjectIdentifierTitle,
.chkApp .searchResultsTable .sapMListTblCell .sapMLnk {
  font-weight:    620;
  letter-spacing: -0.008em;
}

/* Number column â€” always tabular */
.chkApp .searchResultsTable .sapMListTblCell .sapMObjectNumberText,
.chkApp .searchResultsTable .sapMListTblCell .sapMObjectNumber {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1, "kern" 1;
  font-weight: 600;
  letter-spacing: -0.01em;
}

/* Active / pressed row */
.chkApp .searchResultsTable .sapMLIBActive .sapMListTblCell {
  background: rgba(var(--accent-rgb), 0.07) !important;
}

/* Focusable row â€” keyboard nav indicator */
.chkApp .searchResultsTable .sapMLIBFocusable:focus .sapMListTblCell:first-child {
  box-shadow: inset 2px 0 0 rgba(var(--accent-rgb), 0.6);
}

/* Table subrow / popin â€” mobile expanded detail */
.chkApp .searchResultsTable .sapMListTblSubCnt {
  background:  rgba(var(--accent-rgb), 0.025) !important;
  border-top:  1px dashed rgba(var(--accent-rgb), 0.1) !important;
}

.chkApp .searchResultsTable .sapMListTblSubCntHdr {
  font-size:      0.68rem;
  font-weight:    700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color:          var(--text-muted) !important;
  padding:        0.4rem 1rem !important;
}

.chkApp .searchResultsTable .sapMListTblSubCntRow {
  padding: 0.3rem 1rem !important;
}

.chkApp .searchResultsTable .sapMListTblSubCntVal {
  font-size:   0.82rem;
  font-weight: 500;
  color:       var(--text-main) !important;
}

/* Empty state â€” data-aware message */
.chkApp .searchResultsTable .sapMListNoData,
.chkApp .sapMListNoData {
  padding:    3rem 2rem;
}

.chkApp .searchResultsTable .sapMListNoDataText,
.chkApp .sapMListNoDataText {
  font-size:      0.9rem;
  font-weight:    600;
  letter-spacing: 0.01em;
  color:          var(--text-muted);
  text-align:     center;
}

/* Selection column â€” checkbox aligned */
.chkApp .searchResultsTable .sapMListTblSelCol {
  width: 2.75rem !important;
  min-width: 2.75rem !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-5  CHECKBOX â€” precision binary control
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.chkApp .sapMCb {
  display:      inline-flex;
  align-items:  center;
  justify-content: center;
  cursor:       pointer;
  transition:   opacity 140ms ease;
}

.chkApp .sapMCbBg {
  width:         1.1rem;
  height:        1.1rem;
  border-radius: 0.28rem;
  border:        1.5px solid var(--border-soft);
  background:    var(--theme-workbench-control-bg);
  transition:
    border-color 140ms ease,
    background   140ms ease,
    box-shadow   140ms ease;
  display:       flex;
  align-items:   center;
  justify-content: center;
}

.chkApp .sapMCbBg:hover {
  border-color: rgba(var(--accent-rgb), 0.5);
  box-shadow:   0 0 0 3px rgba(var(--accent-rgb), 0.08);
}

/* Checked state */
.chkApp .sapMCbMarkChecked .sapMCbBg,
.chkApp .sapMCb.sapMCbChecked .sapMCbBg {
  background:   rgba(var(--accent-rgb), 1);
  border-color: rgba(var(--accent-rgb), 0.8);
  box-shadow:   0 2px 8px rgba(var(--accent-rgb), 0.28);
}

/* Indeterminate */
.chkApp .sapMCbMarkPartiallyChecked .sapMCbBg {
  background:   rgba(var(--accent-rgb), 0.35);
  border-color: rgba(var(--accent-rgb), 0.55);
}

/* Disabled */
.chkApp .sapMCbRo .sapMCbBg,
.chkApp .sapMCbBg.sapMCbBgDis {
  opacity:    0.42;
  cursor:     not-allowed;
  box-shadow: none;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-6  ICON SYSTEM â€” consistent optical weight
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Contextual icon sizing */
.chkApp .sapMBtn .sapUiIcon {
  font-size:   1em;
  line-height: 1;
  vertical-align: middle;
  flex-shrink: 0;
}

.chkApp .shellActionBtn .sapUiIcon,
.chkApp .shellUserBtn .sapUiIcon {
  font-size:  0.95rem;
  opacity:    0.9;
}

/* Icon inside status chip */
.chkApp .detailRailStatusChip .sapUiIcon,
.chkApp .searchSelectionStatusChip .sapUiIcon,
.chkApp .searchSummaryStatusChip .sapUiIcon,
.chkApp .searchStageStatusChip .sapUiIcon {
  font-size: 0.72rem;
}

/* Muted icons in tables */
.chkApp .sapMListTblCell .sapUiIcon,
.chkApp .sapMListTblCell .sapMObjectStatusIcon {
  opacity: 0.78;
  font-size: 0.88rem;
  vertical-align: middle;
}

/* Semantic status icon colors */
.chkApp .sapMObjStatusError   .sapUiIcon { color: var(--ui-sem-negative-label) !important; }
.chkApp .sapMObjStatusSuccess .sapUiIcon { color: var(--ui-sem-positive-label) !important; }
.chkApp .sapMObjStatusWarning .sapUiIcon { color: var(--ui-sem-critical-label) !important; }
.chkApp .sapMObjStatusInformation .sapUiIcon { color: var(--ui-sem-informative-label) !important; }


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-7  MENU BUTTON â€” split/regular unified
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Split menu button container */
.chkApp .sapMMenuBtn {
  border-radius:    999px;
  overflow:         hidden;
  transition:       box-shadow 180ms ease;
}

.chkApp .sapMMenuBtn:hover {
  box-shadow: 0 4px 14px rgba(var(--accent-rgb), 0.12);
}

/* Regular part (left side of split) */
.chkApp .sapMMenuBtnRegular {
  border-radius:   999px 0 0 999px !important;
  border-right:    1px solid rgba(var(--accent-rgb), 0.12) !important;
  font-weight:     600 !important;
  font-size:       0.77rem !important;
  padding-inline:  0.82rem !important;
  transition:      background 140ms ease, border-color 140ms ease;
}

/* Arrow/dropdown part (right side of split) */
.chkApp .sapMMenuBtnSplit {
  border-radius:   0 999px 999px 0 !important;
  padding-inline:  0.5rem !important;
  border-left:     0 !important;
  transition:      background 140ms ease;
}

.chkApp .sapMMenuBtnRegular:hover,
.chkApp .sapMMenuBtnSplit:hover {
  background: rgba(var(--accent-rgb), 0.07) !important;
}

/* Overflow toolbar menu button */
.chkApp .sapMOverflowToolbarMenuButton .sapMBtnInner,
.chkApp .sapMOTBOverflowButton .sapMBtnInner {
  border-radius: 999px !important;
  background:    var(--theme-workbench-control-bg) !important;
  border-color:  var(--border-soft) !important;
  font-weight:   600 !important;
  font-size:     0.77rem !important;
  transition:    transform 130ms ease, box-shadow 180ms ease,
                 border-color 180ms ease, background 180ms ease;
}

.chkApp .sapMOverflowToolbarMenuButton:hover .sapMBtnInner,
.chkApp .sapMOTBOverflowButton:hover .sapMBtnInner {
  transform:    translateY(-1px);
  box-shadow:   0 4px 12px rgba(var(--accent-rgb), 0.1);
  border-color: rgba(var(--accent-rgb), 0.28);
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-8  MESSAGE STRIP â€” inline feedback banners
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.chkApp .sapMMsgStrip,
.chkApp .sapMMessageStrip {
  border-radius:   0.625rem !important;
  border-width:    1px !important;
  border-style:    solid !important;
  padding:         0.6rem 0.875rem !important;
  font-size:       0.845rem !important;
  font-weight:     500 !important;
  line-height:     1.45 !important;
  display:         flex !important;
  align-items:     flex-start !important;
  gap:             0.5rem !important;
  transition:      opacity 200ms ease, transform 200ms ease;
  animation:       msgStripIn 240ms cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

@keyframes msgStripIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Error */
.chkApp .sapMMsgStripError,
.chkApp .sapMMessageStripError {
  background:   rgba(var(--semantic-danger-rgb), 0.07) !important;
  border-color: rgba(var(--semantic-danger-rgb), 0.28) !important;
  color:        var(--ui-sem-negative-label) !important;
}

/* Warning */
.chkApp .sapMMsgStripWarning,
.chkApp .sapMMessageStripWarning {
  background:   rgba(var(--semantic-warning-rgb), 0.07) !important;
  border-color: rgba(var(--semantic-warning-rgb), 0.28) !important;
  color:        var(--ui-sem-critical-label) !important;
}

/* Success */
.chkApp .sapMMsgStripSuccess,
.chkApp .sapMMessageStripSuccess {
  background:   rgba(var(--semantic-success-rgb), 0.07) !important;
  border-color: rgba(var(--semantic-success-rgb), 0.28) !important;
  color:        var(--ui-sem-positive-label) !important;
}

/* Information */
.chkApp .sapMMsgStripInformation,
.chkApp .sapMMessageStripInformation {
  background:   rgba(var(--semantic-info-rgb, var(--accent-rgb)), 0.07) !important;
  border-color: rgba(var(--semantic-info-rgb, var(--accent-rgb)), 0.28) !important;
  color:        var(--ui-sem-informative-label) !important;
}

/* Strip close button */
.chkApp .sapMMsgStripCloseButton .sapMBtnInner,
.chkApp .sapMMessageStripCloseButton .sapMBtnInner {
  border-radius: 50% !important;
  width:  1.5rem !important;
  height: 1.5rem !important;
  min-width: 1.5rem !important;
  padding: 0 !important;
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
  opacity: 0.65;
  transition: opacity 140ms ease, background 140ms ease;
}

.chkApp .sapMMsgStripCloseButton:hover .sapMBtnInner {
  opacity: 1;
  background: rgba(0, 0, 0, 0.08) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-9  SEGMENTED / ICON TAB BAR (sapMITB*)
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Icon tab container */
.chkApp .sapMITH,
.chkApp .sapMITBHead {
  background:   transparent !important;
  border-bottom: 1px solid rgba(var(--accent-rgb), 0.1) !important;
  gap:           0.15rem;
}

/* Individual tab */
.chkApp .sapMITBFilter {
  border-radius:   0.5rem 0.5rem 0 0 !important;
  border:          0 !important;
  padding:         0.48rem 0.9rem !important;
  cursor:          pointer;
  transition:      background 140ms ease, color 140ms ease;
  position:        relative;
}

.chkApp .sapMITBFilter:hover {
  background: rgba(var(--accent-rgb), 0.06) !important;
}

/* Active tab */
.chkApp .sapMITBSelected {
  background:    rgba(var(--accent-rgb), 0.08) !important;
  border-bottom: 0 !important;
}

/* Active tab underline indicator */
.chkApp .sapMITBSelected::after {
  content:        '';
  position:       absolute;
  inset-block-end: 0;
  inset-inline:    15% 15%;
  height:          2px;
  border-radius:   1px 1px 0 0;
  background:      var(--accent);
  box-shadow:      0 0 6px rgba(var(--accent-rgb), 0.4);
}

/* Tab text */
.chkApp .sapMITBText {
  font-size:      0.8rem !important;
  font-weight:    600 !important;
  letter-spacing: 0.01em !important;
  color:          var(--text-subtle) !important;
  transition:     color 140ms ease;
}

.chkApp .sapMITBSelected .sapMITBText,
.chkApp .sapMITBTextOnly.sapMITBSelected {
  color:       var(--accent) !important;
  font-weight: 700 !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-10  STATUS CHIPS â€” precision semantic palette
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Base chip */
.chkApp .detailRailStatusChip,
.chkApp .searchSelectionStatusChip,
.chkApp .searchSummaryStatusChip,
.chkApp .searchStageStatusChip,
.chkApp .uxStatChip {
  display:         inline-flex;
  align-items:     center;
  gap:             0.3rem;
  border-radius:   999px;
  border:          1px solid;
  padding:         0.22rem 0.62rem;
  font-size:       0.67rem;
  font-weight:     700;
  letter-spacing:  0.07em;
  text-transform:  uppercase;
  line-height:     1;
  white-space:     nowrap;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition:      transform 120ms ease, box-shadow 180ms ease;
}

.chkApp .detailRailStatusChip:hover,
.chkApp .uxStatChip:hover {
  transform:  scale(1.02);
  box-shadow: 0 3px 10px rgba(var(--accent-rgb), 0.12);
}

/* Semantic colour mapping â€” set via JS class or data-attr */
.chkApp .statusChipPositive,
.chkApp [data-semantic="positive"] .detailRailStatusChip {
  background:   rgba(var(--semantic-success-rgb), 0.1) !important;
  border-color: rgba(var(--semantic-success-rgb), 0.32) !important;
  color:        var(--ui-sem-positive-label) !important;
}

.chkApp .statusChipNegative,
.chkApp [data-semantic="negative"] .detailRailStatusChip {
  background:   rgba(var(--semantic-danger-rgb), 0.1) !important;
  border-color: rgba(var(--semantic-danger-rgb), 0.32) !important;
  color:        var(--ui-sem-negative-label) !important;
}

.chkApp .statusChipWarning,
.chkApp [data-semantic="warning"] .detailRailStatusChip {
  background:   rgba(var(--semantic-warning-rgb), 0.1) !important;
  border-color: rgba(var(--semantic-warning-rgb), 0.32) !important;
  color:        var(--ui-sem-critical-label) !important;
}

.chkApp .statusChipInformative {
  background:   rgba(var(--accent-rgb), 0.1) !important;
  border-color: rgba(var(--accent-rgb), 0.32) !important;
  color:        var(--accent) !important;
}

.chkApp .statusChipNeutral {
  background:   rgba(var(--accent-rgb), 0.05) !important;
  border-color: var(--border-soft) !important;
  color:        var(--text-muted) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-11  STAT CHIPS (detail hero board)
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.chkApp .uxStatChip {
  flex-direction: column;
  align-items:    flex-start;
  border-radius:  0.75rem !important;
  padding:        0.62rem 0.82rem;
  font-size:      0.72rem;
  font-weight:    600;
  letter-spacing: 0.04em;
  text-transform: none;
  gap:            0.24rem;
  min-height:     var(--theme-detail-stat-min-height, 4.45rem);
  transition:     transform 140ms ease, box-shadow 200ms ease, border-color 180ms ease;
}

.chkApp .uxStatChip .sapMText:first-child {
  font-size:      0.67rem;
  font-weight:    700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color:          var(--text-muted);
  line-height:    1;
}

.chkApp .uxStatChip .sapMText:last-child {
  font-size:             1.18rem;
  font-weight:           800;
  letter-spacing:        -0.022em;
  color:                 var(--text-main);
  line-height:           1.05;
  font-variant-numeric:  tabular-nums;
  font-feature-settings: "tnum" 1;
}

.chkApp .uxStatChip:hover {
  transform:    translateY(-2px);
  box-shadow:   0 6px 20px rgba(var(--accent-rgb), 0.1) !important;
  border-color: rgba(var(--accent-rgb), 0.22) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-12  POPOVER & SELECT â€” floating surfaces
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Global popover */
.sapMPopover,
.sapMResponsivePopover {
  animation: popoverIn 200ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

@keyframes popoverIn {
  from { opacity: 0; transform: translateY(4px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Select list animation */
.sapMSelectList {
  animation: selectIn 180ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

@keyframes selectIn {
  from { opacity: 0; transform: translateY(-4px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Popover inner list items */
.sapMPopover .sapMList,
.sapMResponsivePopover .sapMList {
  padding: 0.25rem !important;
}

.sapMPopover .sapMLIB,
.sapMResponsivePopover .sapMLIB {
  border-radius: 0.5rem !important;
  margin:        1px 0 !important;
  min-height:    2.2rem !important;
  padding-inline: 0.62rem !important;
  transition:    background 110ms ease !important;
}

/* List item text precision */
.sapMPopover .sapMSLITitleOnly,
.sapMResponsivePopover .sapMSLITitleOnly {
  font-size:   0.845rem !important;
  font-weight: 500 !important;
}

.sapMPopover .sapMSLIDescription,
.sapMResponsivePopover .sapMSLIDescription {
  font-size:   0.76rem !important;
  color:       var(--text-muted) !important;
}

/* Group headers in dropdown */
.sapMSelectList .sapMGroupHeaderListItem,
.sapMPopover .sapMGroupHeaderListItem {
  padding-inline: 0.62rem !important;
  padding-block:  0.48rem 0.2rem !important;
  pointer-events: none;
}

.sapMSelectList .sapMGroupHeaderListItem .sapMSLITitleOnly,
.sapMPopover .sapMGroupHeaderListItem .sapMSLITitleOnly {
  font-size:      0.64rem !important;
  font-weight:    800 !important;
  letter-spacing: 0.09em !important;
  text-transform: uppercase !important;
  color:          var(--text-muted) !important;
  opacity:        0.8 !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-13  DIALOG â€” full modal authority
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Overlay â€” rich scrim */
.sapMDialogBlockLayer,
.sapUiBLy {
  background:
    radial-gradient(ellipse at 50% 0%, rgba(var(--accent-rgb), 0.06), transparent 60%),
    rgba(6, 14, 28, 0.52) !important;
  backdrop-filter: blur(4px) saturate(110%) !important;
  -webkit-backdrop-filter: blur(4px) saturate(110%) !important;
}

body.chkAppRoot.appDark .sapMDialogBlockLayer,
body.chkAppRoot.appDark .sapUiBLy {
  background:
    radial-gradient(ellipse at 50% 0%, rgba(var(--accent-rgb), 0.08), transparent 55%),
    rgba(0, 2, 14, 0.72) !important;
}

/* Dialog enter animation â€” spring, not linear */
.sapMDialog {
  animation: dialogSpringIn 300ms cubic-bezier(0.2, 0.82, 0.36, 1.05) both !important;
}

@keyframes dialogSpringIn {
  from { opacity: 0; transform: translateY(12px) scale(0.972); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Header accent */
.sapMDialog > .sapMBar.sapMHeader-CTX {
  position:  relative;
}

.sapMDialog > .sapMBar.sapMHeader-CTX::after {
  content:     '';
  position:    absolute;
  inset-block-end: 0;
  inset-inline: 0;
  height:      1px;
  background:  linear-gradient(
    90deg,
    transparent,
    rgba(var(--accent-rgb), 0.15) 50%,
    transparent
  );
  pointer-events: none;
}

/* Busy dialog */
.sapMBusyDialog .sapMDialogTitle {
  font-size:      0.9rem !important;
  font-weight:    700 !important;
  letter-spacing: -0.01em !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-14  VALUE HELP / TABLE SELECT DIALOG â€” search dialogs
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

body.chkAppRoot .sapMSelectDialog,
body.chkAppRoot .sapMTableSelectDialog {
  border-radius:   1.25rem !important;
  border:          1px solid var(--border-soft) !important;
  background:      var(--shell-surface) !important;
  box-shadow:
    0 28px 72px rgba(6, 14, 28, 0.2),
    0 8px 24px rgba(6, 14, 28, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.18) !important;
  backdrop-filter: blur(28px) saturate(140%) !important;
  -webkit-backdrop-filter: blur(28px) saturate(140%) !important;
  overflow: hidden !important;
}

body.chkAppRoot.appDark .sapMSelectDialog,
body.chkAppRoot.appDark .sapMTableSelectDialog {
  box-shadow:
    0 28px 72px rgba(0, 2, 18, 0.5),
    0 8px 28px rgba(0, 2, 18, 0.32),
    inset 0 1px 0 rgba(210, 230, 255, 0.05) !important;
}

/* Dialog search bar */
body.chkAppRoot .sapMSelectDialog .sapMSFF,
body.chkAppRoot .sapMTableSelectDialog .sapMSFF {
  border-radius: 999px !important;
  margin: 0.5rem 0.75rem !important;
}

/* Dialog list container */
body.chkAppRoot .sapMSelectDialog .sapMListUl,
body.chkAppRoot .sapMTableSelectDialog .sapMListUl {
  padding: 0.25rem !important;
}

body.chkAppRoot .sapMSelectDialog .sapMLIB,
body.chkAppRoot .sapMTableSelectDialog .sapMLIB {
  border-radius: 0.5rem !important;
  border:        0 !important;
  transition:    background 110ms ease !important;
}

body.chkAppRoot .sapMSelectDialog .sapMLIBSelected,
body.chkAppRoot .sapMTableSelectDialog .sapMLIBSelected {
  background: rgba(var(--accent-rgb), 0.1) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-15  MESSAGE TOAST â€” contextual feedback
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.sapMMessageToast {
  position:  fixed !important;
  z-index:   99999 !important;
  max-width: min(90vw, 26rem) !important;
  word-wrap: break-word !important;
}

/* Semantic toast variants â€” set via JS class */
.sapMMessageToast.toastSuccess {
  border-color: rgba(var(--semantic-success-rgb), 0.36) !important;
  box-shadow:
    0 12px 36px rgba(var(--semantic-success-rgb), 0.14),
    0 4px 12px rgba(6, 14, 28, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.22) !important;
}

.sapMMessageToast.toastError {
  border-color: rgba(var(--semantic-danger-rgb), 0.4) !important;
  box-shadow:
    0 12px 36px rgba(var(--semantic-danger-rgb), 0.16),
    0 4px 12px rgba(6, 14, 28, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.22) !important;
}

.sapMMessageToast.toastWarning {
  border-color: rgba(var(--semantic-warning-rgb), 0.38) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-16  CALENDAR â€” temporal data entry
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Month/year navigation */
.sapUiCalMonthPicker,
.sapUiCalYearPicker {
  padding: 0.5rem !important;
}

.sapUiCalMonthPicker .sapUiCalItem,
.sapUiCalYearPicker .sapUiCalItem {
  border-radius: 0.5rem !important;
  font-size:     0.82rem !important;
  font-weight:   500 !important;
  padding:       0.4rem !important;
  transition:    background 110ms ease, transform 110ms ease !important;
}

.sapUiCalMonthPicker .sapUiCalItem:hover,
.sapUiCalYearPicker .sapUiCalItem:hover {
  background: rgba(var(--accent-rgb), 0.09) !important;
  transform:  scale(1.04) !important;
}

.sapUiCalMonthPicker .sapUiCalItemSel,
.sapUiCalYearPicker .sapUiCalItemSel {
  background:  var(--accent) !important;
  color:       rgba(255, 255, 255, 0.97) !important;
  font-weight: 700 !important;
}

/* Date range selection */
.sapUiCal .sapUiCalItemSelBetween {
  background: rgba(var(--accent-rgb), 0.1) !important;
  border-radius: 0 !important;
}

.sapUiCal .sapUiCalItemSelStart {
  border-top-right-radius:    0 !important;
  border-bottom-right-radius: 0 !important;
}

.sapUiCal .sapUiCalItemSelEnd {
  border-top-left-radius:     0 !important;
  border-bottom-left-radius:  0 !important;
}

/* Week numbers */
.sapUiCal .sapUiCalWeekNum {
  font-size:   0.64rem !important;
  font-weight: 700 !important;
