   Â§ P-21  BUSY / LOADING STATES â€” graceful wait
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Inline busy indicator dots */
.chkApp .sapMBusyIndicator {
  display:        inline-flex !important;
  align-items:    center !important;
  gap:            0.3rem !important;
}

.chkApp .sapMBusyIndicatorDot {
  width:         0.38rem !important;
  height:        0.38rem !important;
  border-radius: 50% !important;
  background:    var(--accent) !important;
  animation:     busyDot 1.1s ease-in-out infinite !important;
}

.chkApp .sapMBusyIndicatorDot:nth-child(2) { animation-delay: 0.18s !important; }
.chkApp .sapMBusyIndicatorDot:nth-child(3) { animation-delay: 0.36s !important; }

@keyframes busyDot {
  0%, 80%, 100% { opacity: 0.22; transform: scale(0.75); }
  40%            { opacity: 1;    transform: scale(1.2); }
}

/* Busy button state */
.chkApp .sapMBtnBusy .sapMBtnInner {
  opacity:  0.72 !important;
  cursor:   wait !important;
  position: relative;
  overflow: hidden;
}

.chkApp .sapMBtnBusy .sapMBtnInner::after {
  content:    '';
  position:   absolute;
  inset-block: 0;
  inset-inline-start: -100%;
  width:      100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.18),
    transparent
  );
  animation: btnBusyShimmer 1.4s linear infinite;
}

@keyframes btnBusyShimmer {
  to { inset-inline-start: 100%; }
}

/* Page-level busy overlay */
.chkApp .sapUiBusy {
  border-radius:   inherit !important;
  background:      rgba(var(--shell-surface, rgba(255,255,255,0.7))) !important;
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-22  OVERFLOW TOOLBAR â€” hidden actions popover
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

