  color:                 var(--text-main) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-25  NAV CONTAINER â€” page transitions
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.chkApp .sapMNavContainer {
  overflow: hidden;
}

/* Slide-in transition for navigating between pages */
.chkApp .sapMNavContainer .sapMPage {
  animation: navPageIn 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

@keyframes navPageIn {
  from { opacity: 0; transform: translateX(16px); }
  to   { opacity: 1; transform: translateX(0); }
}

/* Back navigation â€” slide from other direction */
.chkApp .sapMNavContainer.sapMNavBack .sapMPage {
  animation: navPageBack 280ms cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

@keyframes navPageBack {
  from { opacity: 0; transform: translateX(-12px); }
  to   { opacity: 1; transform: translateX(0); }
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-26  SCROLLBAR â€” system-native feel, branded accent
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Thin everywhere â€” non-intrusive */
.chkApp *,
.sapMDialog *,
.sapMPopover *,
.sapMSelectList * {
  scrollbar-width: thin;
  scrollbar-color: rgba(var(--accent-rgb), 0.22) transparent;
}

.chkApp *::-webkit-scrollbar         { width: 4px; height: 4px; }
.chkApp *::-webkit-scrollbar-track   { background: transparent; }
.chkApp *::-webkit-scrollbar-corner  { background: transparent; }
.chkApp *::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background:    rgba(var(--accent-rgb), 0.22);
  transition:    background 200ms ease;
}

.chkApp *::-webkit-scrollbar-thumb:hover {
  background: rgba(var(--accent-rgb), 0.44);
}

/* Dialogs/popovers scrollbar */
.sapMDialog *::-webkit-scrollbar-thumb,
.sapMPopover *::-webkit-scrollbar-thumb {
  background: rgba(var(--accent-rgb), 0.28);
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-27  FOCUS SYSTEM â€” WCAG AA, visually refined
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Universal reset */
.chkApp :focus                        { outline: none !important; }
.sapMDialog :focus                    { outline: none !important; }
.sapMPopover :focus                   { outline: none !important; }
.sapMSelectList :focus                { outline: none !important; }

/* Keyboard-only focus ring â€” clean double ring */
.chkApp :focus-visible {
  outline:       none !important;
  box-shadow:    0 0 0 2px var(--surface-1, var(--shell-surface)),
                 0 0 0 4px rgba(var(--accent-rgb), 0.55) !important;
  border-radius: inherit !important;
}

/* Button focus â€” ensure ring outside pill */
.chkApp .sapMBtn:focus-visible,
.chkApp .sapMBtn:focus-visible .sapMBtnInner {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--surface-1, #fff),
              0 0 0 4px rgba(var(--accent-rgb), 0.55) !important;
}

/* Input focus â€” inset ring */
.chkApp .sapMInputBaseContentWrapper:focus-within {
  box-shadow:   0 0 0 3px rgba(var(--accent-rgb), 0.1),
                inset 0 0 0 1.5px rgba(var(--accent-rgb), 0.55) !important;
  border-color: rgba(var(--accent-rgb), 0.55) !important;
  outline:      none !important;
}

/* Negative/danger focus */
.chkApp .sapMBtnNegative:focus-visible .sapMBtnInner {
  box-shadow: 0 0 0 2px var(--surface-1, #fff),
              0 0 0 4px rgba(var(--semantic-danger-rgb), 0.5) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-28  DARK THEME SPECIFICS
   Fine-tuning for perfect dark mode rendering
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

body.chkAppRoot.appDark {
  /* Extra saturation in dark glass elements */
  --glass-sat: 160%;
}

body.chkAppRoot.appDark .chkApp .appShellHeader::before {
  background: linear-gradient(
    90deg,
    transparent,
    rgba(var(--accent-rgb), 0.4) 35%,
    rgba(var(--accent-rgb), 0.18) 65%,
    transparent
  );
}

/* Dark KPI cards â€” stronger shadow */
body.chkAppRoot.appDark .chkApp .kpiCard,
body.chkAppRoot.appDark .chkApp .searchAnalyticsCard,
body.chkAppRoot.appDark .chkApp .workflowStageCard {
  box-shadow:
    0 1px 3px rgba(0, 2, 12, 0.3),
    0 2px 8px rgba(0, 2, 12, 0.2),
    inset 0 1px 0 rgba(210, 230, 255, 0.07) !important;
}

/* Dark inputs â€” subtler border */
body.chkAppRoot.appDark .chkApp .sapMInputBaseContentWrapper {
  background: rgba(27, 41, 65, 0.94) !important;
}

/* Dark table â€” alternating subtle rows for legibility */
body.chkAppRoot.appDark .chkApp .searchResultsTable .sapMListTblRow:nth-child(even) .sapMListTblCell {
  background: rgba(255, 255, 255, 0.018) !important;
}

/* Dark message strips â€” more vivid semantic colors */
body.chkAppRoot.appDark .chkApp .sapMMsgStripError {
  background: rgba(var(--semantic-danger-rgb), 0.1) !important;
}

body.chkAppRoot.appDark .chkApp .sapMMsgStripWarning {
  background: rgba(var(--semantic-warning-rgb), 0.1) !important;
}

body.chkAppRoot.appDark .chkApp .sapMMsgStripSuccess {
  background: rgba(var(--semantic-success-rgb), 0.1) !important;
}

/* Dark dialog overlay â€” deeper */
body.chkAppRoot.appDark .sapMDialogBlockLayer {
  backdrop-filter: blur(5px) saturate(130%) !important;
}

/* Dark select list â€” slightly deeper surface */
body.chkAppRoot.appDark .sapMSelectList,
body.chkAppRoot.appDark .sapMComboBoxList {
  background: rgba(17, 29, 47, 0.97) !important;
  border-color: rgba(var(--accent-rgb), 0.18) !important;
}

/* Dark calendar item colors */
body.chkAppRoot.appDark .sapUiCal .sapUiCalDayName {
  color: rgba(var(--accent-rgb), 0.6) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-29  INVERTED BLOCK SCHEME â€” all 4 modes
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Light + Inverted blocks */
body.chkAppRoot.appLight.appInvertedBlockScheme .chkApp .kpiCard,
body.chkAppRoot.appLight.appInvertedBlockScheme .chkApp .searchAnalyticsCard {
  box-shadow:
    0 2px 10px rgba(0, 2, 18, 0.28),
    inset 0 1px 0 rgba(210, 230, 255, 0.12) !important;
}

body.chkAppRoot.appLight.appInvertedBlockScheme .chkApp .sapMCbBg {
  background:   rgba(32, 48, 74, 0.94) !important;
  border-color: rgba(202, 220, 249, 0.36) !important;
}

/* Dark + Inverted blocks (light content on dark bg) */
body.chkAppRoot.appDark.appInvertedBlockScheme .chkApp .kpiCard,
body.chkAppRoot.appDark.appInvertedBlockScheme .chkApp .searchAnalyticsCard {
  box-shadow:
    0 2px 10px rgba(160, 179, 207, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.42) !important;
}

body.chkAppRoot.appDark.appInvertedBlockScheme .chkApp .sapMMsgStripError {
  background:   rgba(var(--semantic-danger-rgb), 0.06) !important;
  border-color: rgba(var(--semantic-danger-rgb), 0.2) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-30  LINKS & INLINE INTERACTIVE TEXT
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

.chkApp .sapMLnk {
  color:           var(--accent) !important;
  font-weight:     500 !important;
  text-decoration: none !important;
  border-bottom:   1px solid rgba(var(--accent-rgb), 0.3) !important;
  transition:      border-color 150ms ease, color 150ms ease !important;
  cursor:          pointer;
}

.chkApp .sapMLnk:hover {
  border-bottom-color: rgba(var(--accent-rgb), 0.8) !important;
  color:               rgba(var(--accent-rgb), 0.85) !important;
}

.chkApp .sapMLnk:active {
  color: rgba(var(--accent-rgb), 0.65) !important;
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-31  RESPONSIVE â€” all breakpoints, no jumps
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

/* Wide â€” luxurious spacing */
@media (min-width: 90rem) {
  .chkApp .kpiCard,
  .chkApp .searchAnalyticsCard,
  .chkApp .workflowStageCard {
    padding: 1.1rem 1.2rem;
  }

  .chkApp .detailSectionCard,
  .chkApp .searchFilterCardDense,
  .chkApp .searchResultsTable {
    padding: 1.1rem 1.15rem;
  }

  .chkApp .uxStatChip {
    padding: 0.7rem 0.9rem;
  }

  .chkApp .appShellHeader {
    padding-inline: 1.25rem;
  }
}

/* Medium â€” balanced */
@media (max-width: 72rem) {
  .chkApp .kpiCard .sapMTitle,
  .chkApp .searchAnalyticsCard .sapMTitle {
    font-size: clamp(1.15rem, 2.2vw, 1.5rem);
  }
}

/* Tablet â€” compact */
@media (max-width: 56rem) {
  .chkApp .uxStatChip {
    flex: 1 1 calc(50% - 0.5rem);
    min-width: calc(50% - 0.5rem);
  }

  .chkApp .detailHeroStatBoard {
    gap: 0.5rem;
  }

  .chkApp .sapMWizardStep {
    padding: 1rem !important;
  }
}

/* Mobile â€” essential info only */
@media (max-width: 40rem) {
  .chkApp .shellContextSubtitle { display: none; }

  .chkApp .shellActionBtn .sapMBtnContent {
    display: none;
  }

  .chkApp .kpiCard,
  .chkApp .searchAnalyticsCard {
    padding: 0.75rem 0.875rem;
  }

  .chkApp .searchResultsTable .sapMListTblRow .sapMListTblCell {
    padding-inline: 0.625rem;
    padding-block:  0.5rem;
  }

  .chkApp .sapMDialog {
    border-radius: 0.875rem 0.875rem 0 0 !important;
    position:      fixed !important;
    inset-block-end: 0 !important;
    inset-inline: 0 !important;
    width:         100% !important;
    max-width:     100% !important;
    margin:        0 !important;
    animation:     mobileDialogIn 300ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
  }

  @keyframes mobileDialogIn {
    from { opacity: 0; transform: translateY(100%); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .chkApp .uxStatChip {
    flex:      1 1 100%;
    min-width: 100%;
  }
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-32  HIGH CONTRAST MEDIA QUERY
   Respects OS-level accessibility settings.
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

@media (forced-colors: active) {
  .chkApp .appShellHeader,
  .chkApp .kpiCard,
  .chkApp .searchAnalyticsCard,
  .chkApp .searchResultsTable,
  .chkApp .detailSectionCard {
    border:       2px solid ButtonText !important;
    backdrop-filter: none !important;
    background:   Canvas !important;
    box-shadow:   none !important;
  }

  .chkApp .sapMBtnEmphasized .sapMBtnInner {
    forced-color-adjust: none;
    background:   Highlight !important;
    color:        HighlightText !important;
    border-color: Highlight !important;
  }

  .chkApp :focus-visible {
    outline:      3px solid Highlight !important;
    box-shadow:   none !important;
  }

  .sapMDialog,
  .sapMPopover,
  .sapMSelectList {
    border:     2px solid ButtonText !important;
    background: Canvas !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
  }

  .chkApp .sapMLnk {
    color:        LinkText !important;
    border-bottom-color: LinkText !important;
  }
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-33  REDUCED MOTION â€” no animation penalty for users
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

@media (prefers-reduced-motion: reduce) {
  .chkApp *,
  .chkApp *::before,
  .chkApp *::after,
  .sapMDialog,
  .sapMPopover,
  .sapMSelectList,
  .sapMMessageToast,
  .sapUiCal .sapUiCalItem,
  .sapMOTBPopover {
    animation-duration:        1ms !important;
    animation-iteration-count: 1 !important;
    transition-duration:       1ms !important;
  }

  .chkApp .kpiCard:hover,
  .chkApp .searchAnalyticsCard:hover,
  .chkApp .workflowStageCard:hover,
  .chkApp .infoCardTile:hover,
  .chkApp .uxStatChip:hover,
  .chkApp .sapMGenericTile:hover,
  .chkApp .sapMListTblRow:hover,
  .chkApp .sapMBtn:not(.sapMBtnDisabled):hover .sapMBtnInner,
  .chkApp .sapMBtn:not(.sapMBtnDisabled):active .sapMBtnInner,
  .chkApp .shellActionBtn:hover .sapMBtnInner {
    transform: none !important;
  }

  .chkApp .appShellHeader::before,
  .chkApp .appShellHeader::after {
    display: none;
  }
}


/* â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
   Â§ P-34  PRINT â€” authoritative, ink-efficient
   â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */

@media print {
  /* Kill all visual effects */
  .chkApp *,
  .sapMDialog *,
  .sapMPopover * {
    backdrop-filter:         none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow:              none !important;
    text-shadow:             none !important;
