  letter-spacing: 0.05em !important;
  text-transform: uppercase !important;
  line-height:    1 !important;
}

.chkApp .sapMSwt.sapMSwtOn .sapMSwtLabelOn {
  color: rgba(255, 255, 255, 0.94) !important;
}

.chkApp .sapMSwt:not(.sapMSwtOn) .sapMSwtLabelOff {
  color: var(--text-muted) !important;
}

/* Hover glow */
.chkApp .sapMSwt:not(.sapMSwtDisabled):hover {
  box-shadow:
    0 0 0 3px rgba(var(--accent-rgb), 0.12),
    inset 0 1px 3px rgba(0, 0, 0, 0.06) !important;
}

.chkApp .sapMSwt.sapMSwtOn:not(.sapMSwtDisabled):hover {
  box-shadow:
    0 4px 16px rgba(var(--accent-rgb), 0.38),
    0 0 0 3px rgba(var(--accent-rgb), 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.24) !important;
}

/* Disabled */
.chkApp .sapMSwt.sapMSwtDisabled {
  opacity: 0.42 !important;
  cursor:  not-allowed !important;
  pointer-events: none !important;
}

/* Dark theme switch */
body.chkAppRoot.appDark .chkApp .sapMSwt:not(.sapMSwtOn) {
  background:
    linear-gradient(135deg,
      rgba(27, 43, 69, 0.96),
      rgba(18, 30, 50, 0.92)) !important;
  border-color: rgba(var(--accent-rgb), 0.22) !important;
  box-shadow:   inset 0 1px 4px rgba(0, 0, 0, 0.36) !important;
}

