  will-change:   transform, opacity !important;
}

.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot:nth-child(1) { animation-delay: 0s !important; }
.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot:nth-child(2) { animation-delay: 0.16s !important; }
.chkApp .sapMBusyIndicator .sapMBusyIndicatorDot:nth-child(3) { animation-delay: 0.32s !important; }

@keyframes _busyBounce {
  0%, 60%, 100% {
    opacity:   0.22;
    transform: translateY(0) scale(0.72);
  }
  30% {
    opacity:   1;
    transform: translateY(-0.36rem) scale(1.15);
    box-shadow: 0 0.36rem 0.5rem rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.24);
  }
}

/* Dark theme: glow on dots */
body.chkAppRoot.appDark .chkApp .sapMBusyIndicator .sapMBusyIndicatorDot {
  background: var(--hz-accent, #4DB1FF) !important;
}

/* â•â• VARIANT B: Spinning ring (large contexts) â•â• */
/* Applied when parent has data-busy-style="ring" or .busyRing */

.chkApp .busyRing::before,
.chkApp [data-busy-style="ring"] .sapMBusyIndicator::before {
  content:       '';
  display:       block;
  width:         1.5rem;
  height:        1.5rem;
  border-radius: 50%;
  border:        2.5px solid rgba(var(--hz-accent-rgb, var(--accent-rgb)), 0.18);
