}

/* Success icon â€” green */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-positive"],
.chkApp .sapMObjStatusStatePositive .sapUiIcon,
.chkApp [data-sap-icon="status-positive"] {
  color:     var(--hz-success, #1A7C40) !important;
  font-size: 1.05em !important;
}

/* Warning icon â€” amber */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-critical"],
.chkApp .sapMObjStatusStateCritical .sapUiIcon,
.chkApp [data-sap-icon="status-critical"] {
  color:     var(--hz-warning, #C35500) !important;
  font-size: 1.05em !important;
}

/* Info icon â€” accent blue */
.chkApp .sapUiIcon.sapMObjStatusIcon[data-sap-ui="icon-status-information"],
.chkApp .sapMObjStatusStateInformation .sapUiIcon,
.chkApp [data-sap-icon="status-information"] {
  color:     var(--hz-accent, var(--accent)) !important;
  font-size: 1.05em !important;
}

/* â”€â”€ Global icon alignment â”€â”€ */

.chkApp .sapUiIcon {
  display:      inline-flex !important;
  align-items:  center !important;
  justify-content: center !important;
  flex-shrink:  0 !important;
  line-height:  1 !important;
  vertical-align: middle !important;
}

/* â”€â”€ Attention icon pulse â”€â”€ */

@keyframes _iconAttention {
  0%, 100% { transform: scale(1); }
  20%       { transform: scale(1.22) rotate(-8deg); }
  40%       { transform: scale(1.18) rotate(6deg); }
  60%       { transform: scale(1.14) rotate(-4deg); }
  80%       { transform: scale(1.10) rotate(2deg); }
}

.chkApp .iconAttention {
  animation: _iconAttention 0.6s ease both;
  animation-delay: 400ms;
}

/* â”€â”€ Notification badge â”€â”€ */

.chkApp .shellNotificationBadge,
.chkApp .notifBadge {
  position:       absolute !important;
  top:            -0.2rem !important;
  right:          -0.2rem !important;
  min-width:      1rem !important;
  height:         1rem !important;
  padding:        0 0.22rem !important;
  border-radius:  999px !important;
  font-size:      0.6rem !important;
  font-weight:    800 !important;
  line-height:    1rem !important;
  text-align:     center !important;
  color:          #fff !important;
  background:     var(--hz-danger, #CC0000) !important;
  border:         2px solid !important;
  animation:      _badgePop 350ms cubic-bezier(0.22, 0.61, 0.36, 1) both,
                  _badgePulse 3s 1s ease-in-out infinite !important;
  z-index:        9 !important;
}

body.chkAppRoot.appLight .chkApp .shellNotificationBadge {
  border-color: rgba(255, 255, 255, 0.95) !important;
}

body.chkAppRoot.appDark .chkApp .shellNotificationBadge {
  border-color: rgba(14, 26, 48, 0.95) !important;
}

@keyframes _badgePop {
  from { transform: scale(0); opacity: 0; }
  70%  { transform: scale(1.15); opacity: 1; }
  to   { transform: scale(1);   opacity: 1; }
}

@keyframes _badgePulse {
  0%,  80%, 100% { box-shadow: 0 0 0 0 rgba(204,0,0,0); }
  40%             { box-shadow: 0 0 0 4px rgba(204,0,0,0.18); }
}

/* â”€â”€ Icon-in-chip status coloring â”€â”€ */

.chkApp .detailRailStatusChip .sapUiIcon,
.chkApp .searchSelectionStatusChip .sapUiIcon,
.chkApp .searchSummaryStatusChip .sapUiIcon {
  flex-shrink: 0 !important;
  font-size:   0.78rem !important;
}

/* â”€â”€ Workflow chip icon â”€â”€ */

.chkApp .detailWorkflowChip .sapUiIcon {
  font-size:   0.75rem !important;
  opacity:     0.82 !important;
}


/* â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
   CH 8 Â· KPI NUMBER â€” count-up reveal animation
   â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â• */

@keyframes _kpiReveal {
  from {
    opacity:   0;
    transform: translateY(8px) scale(0.92);
    filter:    blur(2px);
  }
  to {
    opacity:   1;
    transform: translateY(0) scale(1);
    filter:    blur(0);
  }
}

.chkApp .kpiCard .sapMTitle,
.chkApp .kpiCard .kpiNumber,
.chkApp .kpiCard .sapMObjectNumberText {
