}

.sapMMessageToast.sapMMessageToastSuccess {
  border-color: var(--hz-success-border, rgba(26,124,64,0.32)) !important;
  background:   rgba(245, 253, 248, 0.99) !important;
}

body.chkAppRoot.appDark .sapMMessageToast.sapMMessageToastSuccess {
  background:   rgba(8, 32, 18, 0.98) !important;
  border-color: rgba(93, 193, 34, 0.28) !important;
}

/* Left semantic stripe */
.sapMMessageToast::before {
  content:      '';
  position:     absolute;
  left:         0;
  top:          0.25rem;
