  background: rgba(255, 255, 255, 0.97) !important;
  box-shadow: 0 1px 3px rgba(12,28,52,0.05) !important;
}

body.chkAppRoot.appDark .chkApp .sapMTimelineItemContent {
  background: rgba(18, 30, 54, 0.97) !important;
  box-shadow: 0 1px 4px rgba(0,2,12,0.22) !important;
}

.chkApp .sapMTimelineItem:hover .sapMTimelineItemContent {
  border-color: rgba(var(--hz-accent-rgb, 0,112,242), 0.28) !important;
  box-shadow:   0 3px 10px rgba(var(--hz-accent-rgb, 0,112,242), 0.08) !important;
}

/* Title */
.chkApp .sapMTimelineItemTitle {
  font-size:      0.875rem !important;
  font-weight:    720 !important;
  letter-spacing: -0.01em !important;
  line-height:    1.25 !important;
  margin-bottom:  0.2rem !important;
}

/* Timestamp */
.chkApp .sapMTimelineItemDateTime {
  font-size:      0.72rem !important;
  font-weight:    540 !important;
  letter-spacing: 0.01em !important;
  opacity:        0.55 !important;
  margin-top:     0.35rem !important;
