  0%,  100% { box-shadow: 0 0 0 0 rgba(var(--hz-accent-rgb, 0,112,242), 0.0); }
  50%        { box-shadow: 0 4px 16px rgba(var(--hz-accent-rgb, 0,112,242), 0.22); }
}

@keyframes _pictoOrbit {
  from { transform: rotate(0deg) translateX(0.35rem) rotate(0deg); }
  to   { transform: rotate(360deg) translateX(0.35rem) rotate(-360deg); }
}

