/* Focus ring on grid item */
.chkApp .infoCardGrid .sapFGLI:focus {
  outline: none !important;
}

.chkApp .infoCardGrid .sapFGLI:focus .infoCardTile.mushroomCard {
  box-shadow:   0 0 0 2px var(--hz-accent, #0070F2) !important;
  border-radius:0.875rem !important;
}

